(function(){
'use strict';
const KEY='nawaf-hq-v5';
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason:reason||'smart-command'}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function toast(text){const x=document.querySelector('.toast');if(!x)return;x.textContent=text;x.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>x.classList.remove('show'),2800)}
function preferredIds(text){const q=String(text||'').toLowerCase();if(/مراجعة|جودة|اختبار|تست|qa|تدقيق/.test(q))return ['noura','sara','omar'];if(/كود|برمج|تقني|api|ربط|خطأ|bug|backend|frontend|github|vercel/.test(q))return ['omar','sara','noura'];if(/تصميم|واجهة|تجربة|منتج|ux|ui/.test(q))return ['lian','sara','omar'];if(/فكرة|بحث|فرصة|اقتراح|استكشف|research/.test(q))return ['ideas','sara','omar'];return ['sara','omar','lian','noura','ideas']}
function chooseEmployee(s,text,explicit){if(explicit){const x=(s.employees||[]).find(e=>e.id===explicit);if(x)return x}const busy=new Set(['WORKING','RESEARCHING','REVIEWING']);for(const id of preferredIds(text)){const e=(s.employees||[]).find(x=>x.id===id&&!busy.has(x.status));if(e)return e}for(const id of preferredIds(text)){const e=(s.employees||[]).find(x=>x.id===id);if(e)return e}return (s.employees||[])[0]||null}
async function push(){try{if(window.HQCloudReady)await window.HQCloudReady;if(window.HQCloud?.push)await window.HQCloud.push()}catch{}}
function closeModal(){const m=document.getElementById('modal');if(m)m.classList.remove('open')}
function open(){const s=read(),m=document.getElementById('modal'),d=document.getElementById('dialog');if(!m||!d)return;const projects=s.projects||[],employees=s.employees||[];d.innerHTML=`<h2>توجيه الشركة الذكي</h2><p style="color:var(--muted);margin-top:-4px">اكتب المطلوب فقط. النظام يختار الموظف الأنسب ويجهز المهمة للتنفيذ مباشرة.</p><form class="form" id="smart-command-form"><label class="full">وش تبغى الشركة تسوي؟<textarea id="smart-command-text" name="command" placeholder="مثال: راجع آخر مشاكل مُعِين وحدد السبب والحل ثم جهز تقرير مختصر" required></textarea></label><label>المشروع<select name="projectId"><option value="">عام / الشركة</option>${projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label>الإسناد<select name="employeeId"><option value="">ذكي — اختر الأنسب تلقائيًا</option>${employees.map(e=>`<option value="${esc(e.id)}">${esc(e.name)} — ${esc(e.role||'')}</option>`).join('')}</select></label><label class="full" style="display:flex;align-items:center;gap:8px;flex-direction:row"><input type="checkbox" name="runNow" checked style="width:auto"> شغّل الموظف مباشرة بعد إنشاء المهمة</label><div class="full modal-actions"><button type="button" class="ghost" id="smart-command-cancel">إغلاق</button><button class="primary">✦ نفّذ التوجيه</button></div></form>`;m.classList.add('open');document.getElementById('smart-command-cancel').onclick=closeModal;const f=document.getElementById('smart-command-form');f.onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(f),command=String(fd.get('command')||'').trim();if(!command)return;const state=read(),emp=chooseEmployee(state,command,String(fd.get('employeeId')||''));if(!emp){toast('ما فيه موظف AI متاح حاليًا.');return}const projectId=String(fd.get('projectId')||''),task={id:uid('cmd'),title:command.slice(0,90),details:command,projectId,employeeId:emp.id,status:'READY',progress:0,createdAt:new Date().toISOString(),kind:'CEO_COMMAND'};state.tasks=Array.isArray(state.tasks)?state.tasks:[];state.tasks.unshift(task);emp.status='READY';emp.task=task.title;state.activity=Array.isArray(state.activity)?state.activity:[];state.activity.unshift({id:uid('a'),text:`توجيه مباشر من نواف إلى ${emp.name}: ${task.title}`,type:'REAL',at:new Date().toISOString()});state.activity=state.activity.slice(0,120);write(state,'ceo-smart-command');push();window.NawafHQ3D?.routeEmployee?.(emp.id,'READY');closeModal();const runNow=fd.get('runNow')==='on';toast(`تم إسناد التوجيه إلى ${emp.name}${runNow?' وبدأ التنفيذ':''}`);if(runNow&&window.NawafAgents?.runTask){setTimeout(()=>window.NawafAgents.runTask(task.id),260)}else{document.querySelector('[data-view="tasks"]')?.click()}}}
function intercept(e){const b=e.target.closest('#company-command');if(!b)return;e.preventDefault();e.stopImmediatePropagation();open()}
document.addEventListener('click',intercept,true);
window.NawafSmartCommand={open,chooseEmployee};
})();
